   104|
   105|    if (destinationFile.exists) {
   106|      destinationFile.delete();
   107|    }
   108|
   109|    if (sourceUri.startsWith('http')) {
   110|      const response = await fetch(sourceUri);
   111|      if (!response.ok) {
   112|        throw new Error(`Remote image download failed with status ${response.status}`);
   113|      }
   114|      const arrayBuffer = await response.arrayBuffer();
   115|      destinationFile.create({ intermediates: true, overwrite: true });
   116|      destinationFile.write(new Uint8Array(arrayBuffer));
   117|      console.log('[ImageStorage] Downloaded remote image to:', destinationFile.uri);
   118|      return destinationFile.uri;
   119|    }
