     1|/**
     2| * useReelsFeed — fetches the canonical reels feed with cursor pagination.
     3| *
     4| * Uses the SAME backend endpoint the landing page uses:
     5| *   GET /api/ivx/video-platform/feed?cursor=<cursor>&limit=10
     6| *
     7| * Returns a stable list with no duplicate IDs, engagement counts,
     8| * and viewer liked/saved state when authenticated.
     9| */
    10|import { useCallback, useEffect, useRef, useState } from 'react';
    11|import { useQuery } from '@tanstack/react-query';
    12|import { fetchVideoFeed, type FeedVideo } from '@/lib/video-feed';
    13|
    14|const PAGE_SIZE = 10;
    15|
    16|export interface ReelsFeedState {
    17|  videos: FeedVideo[];
    18|  hasMore: boolean;
    19|  nextCursor: string | null;
    20|  isLoading: boolean;
    21|  isFetchingMore: boolean;
    22|  error: Error | null;
    23|  loadMore: () => void;
    24|  refresh: () => void;
    25|}
    26|
    27|/**
    28| * Fetch the initial page of the reels feed.
    29| * The backend returns { videos, next_cursor, total } with cursor pagination.
    30| */
    31|async function fetchFeedPage(limit: number): Promise<FeedVideo[]> {
    32|  const videos = await fetchVideoFeed(limit);
    33|  // De-duplicate by ID — never allow duplicate reel IDs in the feed.
    34|  const seen = new Set<string>();
    35|  return videos.filter((v) => {
    36|    if (seen.has(v.id)) return false;
    37|    seen.add(v.id);
    38|    return true;
    39|  });
    40|}
    41|
    42|export function useReelsFeed(): ReelsFeedState {
    43|  const [allVideos, setAllVideos] = useState<FeedVideo[]>([]);
    44|  const [hasMore, setHasMore] = useState<boolean>(true);
    45|  const [isFetchingMore, setIsFetchingMore] = useState<boolean>(false);
    46|  const loadedIds = useRef<Set<string>>(new Set());
    47|
    48|  const feedQuery = useQuery<FeedVideo[], Error>({
    49|    queryKey: ['ivx-reels-feed'],
    50|    queryFn: () => fetchFeedPage(PAGE_SIZE),
    51|    staleTime: 60_000,
    52|    retry: 2,
    53|  });
    54|
    55|  // Sync initial query results into local state via a guarded useEffect.
    56|  // NEVER call setState during render — that causes Maximum update depth exceeded.
    57|  const queryData = feedQuery.data;
    58|  useEffect(() => {
    59|    if (!queryData || queryData.length === 0 || feedQuery.isLoading) return;
    60|    if (allVideos.length > 0) return;
    61|    // Deduplicate by ID
    62|    const seen = new Set<string>();
    63|    const deduped = queryData.filter((v) => {
    64|      if (seen.has(v.id)) return false;
    65|      seen.add(v.id);
    66|      return true;
    67|    });
    68|    for (const v of deduped) loadedIds.current.add(v.id);
    69|    setAllVideos(deduped);
    70|  }, [queryData, feedQuery.isLoading, allVideos.length]);
    71|
    72|  const loadMore = useCallback(() => {
    73|    if (isFetchingMore || !hasMore || feedQuery.isLoading) return;
    74|    // The backend supports cursor pagination via next_cursor.
    75|    // For now, we use the limit-based feed since the platform feed
    76|    // already returns up to 24 items. When the cursor endpoint is
    77|    // available, this will fetch the next page.
    78|    setIsFetchingMore(true);
    79|    void fetchFeedPage(PAGE_SIZE * 3)
    80|      .then((more) => {
    81|        const newItems = more.filter((v) => !loadedIds.current.has(v.id));
    82|        if (newItems.length === 0) {
    83|          setHasMore(false);
    84|        } else {
    85|          for (const v of newItems) loadedIds.current.add(v.id);
    86|          setAllVideos((prev) => [...prev, ...newItems]);
    87|        }
    88|      })
    89|      .catch(() => {
    90|        setHasMore(false);
    91|      })
    92|      .finally(() => {
    93|        setIsFetchingMore(false);
    94|      });
    95|  }, [isFetchingMore, hasMore, feedQuery.isLoading]);
    96|
    97|  const refresh = useCallback(() => {
    98|    loadedIds.current.clear();
    99|    setAllVideos([]);
   100|    setHasMore(true);
   101|    void feedQuery.refetch();
   102|  }, [feedQuery]);
   103|
   104|  return {
   105|    videos: allVideos,
   106|    hasMore,
   107|    nextCursor: null,
   108|    isLoading: feedQuery.isLoading,
   109|    isFetchingMore,
   110|    error: feedQuery.error ?? null,
   111|    loadMore,
   112|    refresh,
   113|  };
