   513|async function compressOnWeb(blob: Blob, mimeType: string): Promise<{ blob: Blob; mimeType: string }> {
   514|  if (Platform.OS !== 'web') return { blob, mimeType };
   515|  try {
   516|    const bitmap = await createImageBitmap(blob);
   517|    let w = bitmap.width;
   518|    let h = bitmap.height;
   519|    console.log('[PhotoUpload] Web original dimensions:', w, 'x', h, 'size:', (blob.size / 1024).toFixed(0), 'KB');
   520|
   521|    if (w > MAX_DIMENSION || h > MAX_DIMENSION) {
   522|      const ratio = Math.min(MAX_DIMENSION / w, MAX_DIMENSION / h);
   523|      w = Math.round(w * ratio);
   524|      h = Math.round(h * ratio);
   525|      console.log('[PhotoUpload] Web scaled to:', w, 'x', h);
   526|    }
   527|
   528|    const canvas = new OffscreenCanvas(w, h);
   529|    const ctx = canvas.getContext('2d');
   530|    if (!ctx) return { blob, mimeType };
   531|    ctx.drawImage(bitmap, 0, 0, w, h);
   532|
   533|    let compressed = await canvas.convertToBlob({ type: 'image/jpeg', quality: COMPRESSION_QUALITY_WEB });
   534|    console.log('[PhotoUpload] Web compress:', (blob.size / 1024).toFixed(0), 'KB ->', (compressed.size / 1024).toFixed(0), 'KB at', w, 'x', h);
   535|
   536|    if (compressed.size > MAX_WEB_SIZE_KB * 1024) {
   537|      const retryW = Math.round(w * COMPRESSION_RETRY_DIM_FACTOR);
   538|      const retryH = Math.round(h * COMPRESSION_RETRY_DIM_FACTOR);
   539|      const retryCanvas = new OffscreenCanvas(retryW, retryH);
   540|      const retryCtx = retryCanvas.getContext('2d');
   541|      if (retryCtx) {
   542|        retryCtx.drawImage(bitmap, 0, 0, retryW, retryH);
   543|        compressed = await retryCanvas.convertToBlob({ type: 'image/jpeg', quality: COMPRESSION_QUALITY_WEB_RETRY });
   544|        console.log('[PhotoUpload] Web re-compress:', (compressed.size / 1024).toFixed(0), 'KB at', retryW, 'x', retryH);
   545|      }
   546|    }
   547|    bitmap.close();
   548|    return { blob: compressed, mimeType: 'image/jpeg' };
   549|  } catch (err) {
   550|    console.log('[PhotoUpload] Web compression failed:', (err as Error)?.message);
