   161|export async function uploadProjectMedia(
   162|  projectId: string,
   163|  fileUri: string,
   164|  mediaType: 'image' | 'video',
   165|  title?: string,
   166|): Promise<MediaUploadResult> {
   167|  try {
   168|    const fileName = `${projectId}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${mediaType === 'video' ? 'mp4' : 'jpg'}`;
   169|    const bucket = mediaType === 'video' ? 'project-videos' : 'project-photos';
   170|
   171|    // Upload to Supabase Storage
   172|    const response = await fetch(fileUri);
   173|    const blob = await response.blob();
   174|
   175|    const { data: uploadData, error: uploadError } = await supabase.storage
   176|      .from(bucket)
   177|      .upload(fileName, blob, {
   178|        contentType: mediaType === 'video' ? 'video/mp4' : 'image/jpeg',
   179|        upsert: false,
   180|      });
   181|
   182|    if (uploadError) throw new Error(uploadError.message);
   183|
   184|    const { data: urlData } = supabase.storage.from(bucket).getPublicUrl(fileName);
   185|    const publicUrl = urlData.publicUrl;
   186|
   187|    // Create media record
   188|    const { data: mediaRecord, error: mediaError } = await supabase
   189|      .from('project_media')
   190|      .insert({
   191|        project_id: projectId,
   192|        media_type: mediaType,
   193|        url: publicUrl,
   194|        thumbnail_url: mediaType === 'image' ? publicUrl : null,
   195|        title: title || null,
   196|        position: 0,
   197|      })
   198|      .select()
   199|      .single();
   200|
   201|    if (mediaError) throw new Error(mediaError.message);
   202|
   203|    const result: MediaUploadResult = { success: true, media: mediaRecord as ProjectMedia };
   204|
   205|    if (mediaType === 'video') {
   206|      const { data: videoRecord, error: videoError } = await supabase
   207|        .from('project_videos')
   208|        .insert({
   209|          project_id: projectId,
   210|          media_id: mediaRecord.id,
   211|          video_url: publicUrl,
   212|          title: title || null,
   213|          duration_sec: 0,
   214|        })
   215|        .select()
   216|        .single();
   217|
   218|      if (videoError) throw new Error(videoError.message);
   219|      result.video = videoRecord as ProjectVideo;
   220|    }
   221|
   222|    return result;
   223|  } catch (err) {
   224|    return { success: false, error: (err as Error).message };
