     4|/**
     5| * Conversation persistence for the in-app Chat. Messages are saved per chat
     6| * `source` so a conversation resumes after the app restarts, while staying
     7| * bounded so old turns never bloat storage. Attachments still uploading at
     8| * save time are normalized to a stable state so a resumed conversation never
     9| * shows a permanent "uploading" spinner.
    10| */
    11|
    12|const KEY_PREFIX = '@ivx_chat_history_v1:';
    13|const MAX_PERSISTED_MESSAGES = 80;
    14|const HISTORY_MAX_AGE_MS = 24 * 60 * 60 * 1000; // 24 hours — stale conversations expire
    15|
    16|function storageKey(source: string): string {
    17|  return `${KEY_PREFIX}${source}`;
    18|}
    19|
    20|function normalizeForPersistence(messages: ChatMessage[]): ChatMessage[] {
    21|  return messages.slice(-MAX_PERSISTED_MESSAGES).map((message) => {
    22|    if (!message.attachments || message.attachments.length === 0) {
    23|      return message;
    24|    }
    25|
    26|    return {
    27|      ...message,
    28|      attachments: message.attachments.map((attachment) => {
    29|        if (attachment.status === 'uploading') {
    30|          return attachment.url
    31|            ? { ...attachment, status: 'ready' as const }
    32|            : { ...attachment, status: 'failed' as const, error: attachment.error ?? 'Upload was interrupted.' };
    33|        }
    34|        return attachment;
    35|      }),
    36|    };
    37|  });
    38|}
