    40|/** Load a previously saved conversation for a chat source, or null if none.
    41| *  Conversations older than 24h are automatically discarded so the user
    42| *  always sees their most recent chat, not a stale thread from months ago. */
    43|export async function loadChatHistory(source: string): Promise<ChatMessage[] | null> {
    44|  try {
    45|    const raw = await AsyncStorage.getItem(storageKey(source));
    46|    if (!raw) {
    47|      return null;
    48|    }
    49|
    50|    const parsed = JSON.parse(raw) as ChatMessage[];
    51|    if (!Array.isArray(parsed) || parsed.length === 0) {
    52|      return null;
    53|    }
    54|
    55|    const now = Date.now();
    56|    const recent = parsed.filter((message) => {
    57|      if (typeof message?.id !== 'string' || typeof message?.message !== 'string') {
    58|        return false;
    59|      }
    60|      const ts = new Date(message.timestamp).getTime();
    61|      if (Number.isNaN(ts)) return true; // keep messages with unparseable timestamps
    62|      return now - ts < HISTORY_MAX_AGE_MS;
    63|    });
    64|
    65|    if (recent.length === 0) {
    66|      // All messages expired — clear stale storage so next load is clean
    67|      await AsyncStorage.removeItem(storageKey(source));
    68|      return null;
    69|    }
    70|
    71|    // Sort by timestamp ascending (oldest first, newest last) so the
    72|    // FlatList renders chronologically and scrollToEnd lands on the latest.
    73|    recent.sort((a, b) => {
    74|      const ta = new Date(a.timestamp).getTime();
    75|      const tb = new Date(b.timestamp).getTime();
    76|      if (Number.isNaN(ta) && Number.isNaN(tb)) return 0;
    77|      if (Number.isNaN(ta)) return 1;
    78|      if (Number.isNaN(tb)) return -1;
    79|      return ta - tb;
    80|    });
    81|
    82|    return recent;
    83|  } catch (error) {
    84|    console.log('[ChatPersistence] Load failed:', (error as Error)?.message);
    85|    return null;
    86|  }
