   161|    method: options.method ?? 'GET',
   162|    headers,
   163|    body: options.body ? JSON.stringify(options.body) : undefined,
   164|  });
   165|
   166|  const text = await response.text();
   167|  let parsed: Record<string, unknown> = {};
   168|  try {
   169|    parsed = text ? (JSON.parse(text) as Record<string, unknown>) : {};
   170|  } catch {
